var PB=null;

var A,N='Miguel',T=3,face='<img class="face" src="img/nv/rico.jpg" alt="Rico">';
function say(t){return '<div class="row">'+face+'<div class="bub" id="say">'+t+'</div></div>'}
function setSay(t){document.getElementById('say').innerHTML=t}
function confetti(big){var c=['#f5b400','#2459e6','#0e9a63','#f08a24','#e0457b','#8a5cf6'],m=big?60:30;for(var j=0;j<m;j++){var e=document.createElement('i');e.className='cf';e.style.left=(Math.random()*100)+'vw';e.style.background=c[j%c.length];e.style.setProperty('--dx',((Math.random()-.5)*160)+'px');e.style.setProperty('--rot',((Math.random()-.5)*900)+'deg');e.style.animationDelay=(Math.random()*.35)+'s';e.style.animationDuration=(1.2+Math.random()*.9)+'s';(document.getElementById('phu')||document.body).appendChild(e);setTimeout(function(x){x.remove()},2600,e)}}
function bars(c,t){var b='';for(var j=0;j<t;j++)b+='<i class="'+(j<=c?'on':'')+'"></i>';return '<div class="bars">'+b+'</div>'}
function hdr(c){return '<div class="top"><button class="back" id="bk">‹ Retour</button>'+bars(c,T)+'</div>'}
function shuf(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a}
/* ===== LES 12 LEÇONS ===== */
var POS=[[22,28],[72,32],[30,66],[72,68],[50,48]];
var L=[
{e:'☀️',t:`Le Soleil`,q:["Qu'est-ce que le Soleil ?", "Qu'est-ce que le Soleil nous donne ?", "Que fait le Soleil à l'eau de la mer ?"],img:'soleil.jpg',fx:'zoom',st:[`Le <b>Soleil</b> est une étoile, très loin de la Terre.`,`Il nous donne de la <b>lumière</b> et de la <b>chaleur</b>. Ses rayons aident aussi les plantes à pousser.`,`Il chauffe l'eau des mers, des lacs et des rivières. Une partie devient de la <b>vapeur</b> et monte dans l'air.`],ret:`Le Soleil nous apporte lumière et chaleur. Il joue un rôle essentiel dans le cycle de l'eau.`},
{e:'💧',t:`L'eau`,q:["Pourquoi a-t-on besoin d'eau ?", "Où trouve-t-on de l'eau ?", "Sous quelles formes existe l'eau ?"],img:'goutte.jpg',fx:'zoom',st:[`L'eau est indispensable à la vie : les humains, les animaux et les plantes en ont besoin.`,`On en trouve dans les mers, les rivières, les lacs, sous la terre, dans les glaciers et dans l'air.`,`L'eau a <b>3 états</b> : 🧊 <b>solide</b> (glace, neige), 💧 <b>liquide</b>, ☁️ <b>gazeux</b> (la vapeur, invisible).`],ret:`L'eau peut être solide, liquide ou gazeuse. Elle change d'état selon la température.`},
{e:'☁️',t:`Les nuages`,q:["De quoi est fait un nuage ?", "Comment l'eau monte-t-elle dans le ciel ?", "Comment se forme un nuage ?"],img:'nuage.jpg',emo:'☁️',imgs:['nuage_ville.jpg','nuage_v2.mp4','nuage_v1.mp4'],fx:'zoom',st:[`Un <b>nuage</b> est fait de minuscules gouttelettes d'eau ou de petits cristaux de glace qui flottent dans l'air.`,`Le Soleil chauffe l'eau : elle devient de la vapeur invisible qui <b>monte</b> et se refroidit.`,`Elle se <b>condense</b> en gouttelettes : un nuage se forme ! Blancs et légers, ou gris et épais (pluie, orage).`],ret:`Un nuage est un ensemble de minuscules gouttes d'eau et/ou de cristaux de glace.`},
{e:'🌧️',t:`La pluie`,q:["Que se passe-t-il dans un nuage ?", "Pourquoi la pluie tombe-t-elle ?", "À quoi sert la pluie ? Et si il y en a trop ?"],img:'pluie.jpg',fx:'rain',st:[`Dans un nuage, les petites gouttelettes se rencontrent et <b>grossissent</b>.`,`Quand elles deviennent assez lourdes, elles <b>tombent</b> : c'est la pluie.`,`La pluie arrose les plantes et remplit les rivières. Quand il pleut énormément, l'eau peut déborder : une <b>inondation</b>.`],ret:`La pluie est faite de gouttes d'eau qui tombent des nuages.`},
{e:'🌫️',t:`Le brouillard`,q:["À quoi ressemble le brouillard ?", "De quoi est-il fait ?", "Que voit-on quand il y a du brouillard ?"],img:'brouillard.jpg',img2:'brouillard2.jpg',sw:2,fx:'fog',st:[`Le <b>brouillard</b> ressemble à un nuage qui se forme tout près du sol.`,`Il est fait de minuscules gouttelettes d'eau qui flottent dans l'air.`,`Avec du brouillard, on voit moins loin : les arbres et les voitures semblent flous.`],pro:`Sur la route, les conducteurs ralentissent et gardent plus de distance.`,ret:`Le brouillard est un nuage au niveau du sol.`},
{e:'🌀',t:`L'ouragan`,q:["Où se forme un ouragan ?", "Que trouve-t-on au centre d'un ouragan ?", "Que provoque un ouragan ?"],img:'ouragan.jpg',img2:'ouragan2.jpg',sw:1,img3:'ouragan3.jpg',sw3:2,fx:'spin',st:[`Un <b>ouragan</b> est une très grande tempête qui se forme au-dessus des océans tropicaux très chauds.`,`Il tourne autour d'une zone centrale, <b>l'œil</b>, qui peut être assez calme.`,`Il apporte des vents très violents, de fortes pluies, de grosses vagues et des inondations. On l'appelle aussi cyclone ou typhon.`],pro:`On écoute les consignes, on reste à l'abri et on ne sort pas pour regarder la tempête.`,ret:`Un ouragan est une puissante tempête tournante qui se forme au-dessus des eaux chaudes des océans.`},
{e:'🌋',t:`Le volcan`,q:["Qu'y a-t-il sous la Terre ?", "Comment s'appelle le magma qui sort du volcan ?", "Que sort-il d'autre pendant une éruption ?"],img:'vol_coupe.jpg',img2:'vol_eruption.jpg',sw:2,fx:'zoom',st:[`Sous la Terre, des roches peuvent fondre et former du <b>magma</b>.`,`Quand le magma monte et sort par le volcan, on l'appelle de la <b>lave</b>. Elle est très chaude et coule sur les pentes.`,`Pendant une éruption, des cendres, des gaz et des morceaux de roche sont aussi projetés dans l'air.`],ret:`Le magma est sous la Terre ; la lave est le magma qui arrive à la surface.`},
{e:'⛈️',t:`La tempête`,q:["Qu'est-ce qu'une tempête ?", "Qu'apporte une tempête ?", "Que peut faire le vent d'une tempête ?"],img:'tempete.jpg',fx:'shake',st:[`Une <b>tempête</b> est un épisode de météo très agité, sur terre ou en mer.`,`Elle apporte des vents forts, de fortes pluies, parfois de la grêle et de grosses vagues près des côtes.`,`Le vent peut faire tomber des branches, déraciner des arbres ou déplacer des objets mal attachés.`],pro:`On reste à l'intérieur, loin des fenêtres, et on ne se promène pas sous les arbres.`,ret:`Une tempête est un épisode de vents forts, parfois avec de la pluie ou d'autres phénomènes.`},
{e:'⚡',t:`L'éclair et le tonnerre`,q:["Qu'est-ce qu'un éclair ?", "D'où vient le bruit du tonnerre ?", "Pourquoi voit-on l'éclair avant d'entendre le tonnerre ?"],img:'eclair.jpg',emo:'⚡',imgs:['eclair.jpg','eclair2.jpg','eclair3.jpg'],snd:'thunder',fx:'flash',st:[`Un <b>éclair</b> est une immense décharge électrique dans un nuage d'orage, ou entre le nuage et le sol.`,`Il chauffe très vite l'air autour de lui. L'air se dilate d'un coup et fait un grand bruit : le <b>tonnerre</b>.`,`On voit l'éclair avant d'entendre le tonnerre, car la <b>lumière</b> voyage beaucoup plus vite que le <b>son</b>.`],pro:`Pendant un orage, on entre dans un bâtiment fermé ou une voiture fermée. On évite les arbres isolés, les grands espaces et l'eau.`,ret:`L'éclair est la lumière de la décharge électrique ; le tonnerre est le bruit qu'elle provoque.`},
{e:'🌍',t:`Le séisme`,q:["De quoi est faite la surface de la Terre ?", "Comment un séisme se produit-il ?", "Un séisme est-il toujours dangereux ?"],img:'seisme.jpg',emo:'🌍',imgs:['','seisme.jpg','seisme2.jpg'],snd:'quake',fx:'shake',st:[`La surface de la Terre est faite de grandes plaques de roche, les <b>plaques tectoniques</b>. Elles bougent très lentement.`,`Parfois, des roches se bloquent puis glissent d'un coup. Cela fait trembler le sol : c'est un <b>séisme</b>.`,`Un séisme peut être léger ou faire de gros dégâts. Sous la mer, il peut provoquer un tsunami.`],pro:`On se baisse, on se protège sous une table solide, on protège sa tête et on attend la fin des secousses.`,ret:`Un séisme est un tremblement du sol provoqué par un mouvement brusque des roches en profondeur.`},
{e:'🌊',t:`Le tsunami`,q:["Qu'est-ce qu'un tsunami ?", "À quelle vitesse avance la vague au large ?", "Que fait la vague près de la côte ?"],img:'tsunami.jpg',emo:'🌊',vids:['tsu1.mp4','tsu2.mp4','tsu3.mp4'],fx:'wave',st:[`Un <b>tsunami</b> est une série de très grosses vagues. Il est le plus souvent provoqué par un <b>séisme sous la mer</b>.`,`Au large, la vague est peu visible mais elle avance très vite, comme un avion.`,`Près de la côte, elle grandit et peut envahir la plage et les maisons : c'est une inondation brutale.`],pro:`Si la mer se retire d'un coup ou si une alerte sonne, on s'éloigne tout de suite de la côte et on monte sur un endroit haut.`,ret:`Un tsunami est une série de grosses vagues, souvent causée par un séisme sous la mer.`},
{e:'🌪️',t:`La tornade`,q:["Qu'est-ce qu'une tornade ?", "Que peuvent faire ses vents ?", "Est-elle plus grande qu'un ouragan ?"],img:'tornade0.jpg',emo:'🌪️',imgs:['tornade0.jpg','tornade.jpg','tornade3.jpg'],snd:'wind',fx:'shake',st:[`Une <b>tornade</b> est une colonne d'air qui tourne très vite. Elle relie un nuage d'orage au sol et ressemble à un entonnoir.`,`Ses vents sont extrêmement violents : elle peut soulever des objets, abîmer des maisons et arracher des arbres.`,`Elle est plus petite et plus localisée qu'un ouragan, mais ses vents peuvent être très puissants.`],pro:`On rejoint une pièce intérieure au rez-de-chaussée ou un abri solide, loin des fenêtres, et on protège sa tête.`,ret:`Une tornade est une colonne d'air qui tourne très vite entre un nuage d'orage et le sol.`},
{e:'🔄',t:`Le cycle de l'eau`,q:["Que fait le Soleil à l'eau, et que deviennent la vapeur et les nuages ?","Que se passe-t-il quand les nuages sont lourds ?","Où va l'eau qui est tombée ?"],img:'cycle3.jpg',img2:'cycle4.jpg',sw:2,fx:'zoom',st:[`<b>1. Évaporation</b> : le Soleil chauffe la mer et les rivières, l'eau monte en vapeur. <b>2. Condensation</b> : en haut, elle se refroidit et forme les nuages.`,`<b>3. Précipitations</b> : quand les nuages sont lourds, l'eau retombe en pluie, en neige ou en grêle.`,`<b>4. Ruissellement et infiltration</b> : l'eau coule vers les rivières et la mer, ou s'infiltre dans la terre. Puis le Soleil la chauffe à nouveau : le cycle recommence !`],ret:`Le Soleil chauffe l'eau, la vapeur forme les nuages, l'eau retombe, puis retourne vers les rivières, la terre et les mers. Le cycle recommence sans cesse.`}
];
