function cartes(){var k=0,got=0;function show(){PB=k>0?function(){k--;show()}:null;A.innerHTML=hdr(0)+'<div class="card"><span class="lead">Étape 1 · Les cartes</span><h2>Carte '+(k+1)+' / '+CA.length+'</h2>'+say('Réfléchis, puis <b>touche la carte</b> pour la retourner !')+'<div class="fl" id="fl"><div class="in"><div class="f"><div class="e">'+CA[k][0]+'</div><div class="q">'+CA[k][1]+'</div><small>👆 Touche pour voir</small></div><div class="b"><div class="e">✅</div><div class="q">'+CA[k][2]+'</div></div></div></div><div class="btns" id="bb" style="display:none"><button class="go" id="ok" style="background:#0e9a63">😀 Je savais</button><button class="go" id="ko" style="background:#f08a24">🤔 À revoir</button></div></div>';
  document.getElementById('fl').onclick=function(){this.classList.add('on');document.getElementById('bb').style.display='flex'};
  function nx(g){if(g)got++;if(k<CA.length-1){k++;show()}else fin()}
  document.getElementById('ok').onclick=function(){nx(1)};document.getElementById('ko').onclick=function(){nx(0)}}
 function fin(){PB=function(){k=CA.length-1;show()};A.innerHTML=hdr(0)+'<div class="card"><span class="lead">Étape 1 · Les cartes</span><h2>Cartes terminées !</h2>'+say('Tu savais <b>'+got+' carte'+(got>1?'s':'')+' sur '+CA.length+'</b>. Maintenant, tu vas <b>animer</b> le cours toi-même !')+'<div class="btns"><button class="go" id="nx">▶️ Commencer le cours</button></div></div>';confetti(1);document.getElementById('nx').onclick=function(){course(0)}}
 show()}
