 var im=D.imgs?'<div class="emo" id="emo">'+D.emo+'</div>'+D.imgs.map(function(v,j){return !v?'':/\.mp4$/.test(v)?'<video class="sl" id="iv'+j+'" src="img/phen/'+v+'" muted loop playsinline preload="auto"></video>':'<img class="sl" id="iv'+j+'" src="img/phen/'+v+'" alt="">'}).join(''):D.vids?'<div class="emo" id="emo">'+D.emo+'</div>'+D.vids.map(function(v,j){return '<video class="sl vd" id="iv'+j+'" src="img/phen/'+v+'" muted loop playsinline preload="auto"></video>'}).join(''):D.emo?'<div class="emo" id="emo">'+D.emo+'</div>':'<img class="sl on" id="i1" src="img/phen/'+D.img+'" alt="">'+(D.img2?'<img class="sl" id="i2" src="img/phen/'+D.img2+'" alt="">':'')+(D.img3?'<img class="sl" id="i3" src="img/phen/'+D.img3+'" alt="">':'');
