 var h=document.getElementById('hsp'),st=document.getElementById('stg');[D.img,D.img2,D.img3].concat(D.imgs||[]).forEach(function(u){if(u&&!/\.mp4$/.test(u)){var pi=new Image();pi.src='img/phen/'+u}});function ar(id){var e=document.getElementById(id);if(!e)return;if(D.vids){return}function g(){if(e.naturalWidth)st.style.aspectRatio=e.naturalWidth+'/'+e.naturalHeight}if(e.complete)g();else e.onload=g}ar('i1');
