/* ===== 3. EXERCICES ===== */
var X1=[['Je suis un nuage tout près du sol.','🌫️','Brouillard'],['Je suis une montagne qui crache de la lave.','🌋','Volcan'],['Je suis une grande tempête qui tourne sur l\'océan, avec un œil.','🌀','Ouragan'],['Je suis fait de gouttelettes et je flotte dans le ciel.','☁️','Nuage'],['Je tombe des nuages et j\'arrose les plantes.','🌧️','Pluie'],['Je suis le voyage de l\'eau entre la mer, le ciel et la terre.','🔄','Cycle de l\'eau'],['Je suis la lumière d\'un orage.','⚡','Éclair'],['Je fais trembler le sol.','🌍','Séisme'],['Je suis une énorme vague qui envahit la côte.','🌊','Tsunami'],['Je suis une colonne d\'air qui tourne très vite.','🌪️','Tornade']];
function exo1(){var q=0,ok=0;function show(){PB=q>0?function(){q--;show()}:function(){course(L.length-1)};var c=X1[q],o=shuf([c].concat(shuf(X1.filter(function(x){return x!==c})).slice(0,2)));
  A.innerHTML=hdr(2)+'<div class="card"><span class="lead">Étape 3 · Exercice 1 / 3 · Question '+(q+1)+' / '+X1.length+'</span><h2>Qui suis-je ?</h2>'+say(c[0])+'<div class="thr">'+o.map(function(x){return '<button class="th" data-k="'+(x===c?1:0)+'" style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font:800 .8rem var(--display);padding:8px 2px;aspect-ratio:auto"><span style="font-size:2.4rem">'+x[1]+'</span>'+x[2]+'</button>'}).join('')+'</div><div class="btns" id="bb"></div></div>';
  A.querySelectorAll('.th').forEach(function(b){b.onclick=function(){if(b.disabled)return;if(b.dataset.k==='1'){ok++;b.classList.add('ok');confetti();setSay('Oui ! Je suis <b>'+c[2]+'</b> ! 🎉');A.querySelectorAll('.th').forEach(function(x){x.disabled=true});document.getElementById('bb').innerHTML='<button class="go" id="nx">'+(q<X1.length-1?'Suivant ›':'Continuer ›')+'</button>';document.getElementById('nx').onclick=function(){if(q<X1.length-1){q++;show()}else exo2()}}else{b.classList.add('no');setSay('Pas celui-là. Relis bien !')}}})}
 show()}
var X2=[['Le brouillard est un nuage près du sol.',1],['Le magma est la lave qui coule à l\'extérieur du volcan.',0],['Le tonnerre est le bruit provoqué par l\'éclair.',1],['Une tornade est une colonne d\'air qui tourne très vite.',1],['Le Soleil participe au cycle de l\'eau.',1],['Un tsunami est souvent causé par un séisme sous la mer.',1]];
function exo2(){var q=0;function show(){PB=q>0?function(){q--;show()}:function(){exo1()};var c=X2[q];A.innerHTML=hdr(2)+'<div class="card"><span class="lead">Étape 3 · Exercice 2 / 3 · Question '+(q+1)+' / '+X2.length+'</span><h2>Vrai ou faux ?</h2>'+say('Lis bien, puis choisis !')+'<div class="gsc" style="font-size:1.15rem">'+c[0]+'</div><div class="gch" style="grid-template-columns:1fr 1fr"><button class="opt" data-v="1" style="font-size:2rem">✅<small>Vrai</small></button><button class="opt" data-v="0" style="font-size:2rem">❌<small>Faux</small></button></div><div class="btns" id="bb"></div></div>';
  A.querySelectorAll('.opt').forEach(function(b){b.onclick=function(){if(+b.dataset.v===c[1]){b.classList.add('ok');confetti();setSay('Bravo ! 🎉');A.querySelectorAll('.opt').forEach(function(x){x.disabled=true});document.getElementById('bb').innerHTML='<button class="go" id="nx">'+(q<X2.length-1?'Suivant ›':'Continuer ›')+'</button>';document.getElementById('nx').onclick=function(){if(q<X2.length-1){q++;show()}else exo3()}}else{b.classList.add('no');setSay('Pas tout à fait. Réfléchis encore !')}}})}
 show()}
var X3=['☀️ Le Soleil chauffe l\'eau','💨 La vapeur monte','☁️ Un nuage se forme','🌧️ Il pleut','🌊 L\'eau rejoint les rivières et la mer'];
function exo3(){PB=function(){exo2()};var n=0,o=shuf(X3.map(function(x,i){return [x,i]}));A.innerHTML=hdr(2)+'<div class="card"><span class="lead">Étape 3 · Exercice 3 / 3</span><h2>Remets dans l\'ordre</h2>'+say('Touche les étapes du cycle de l\'eau <b>dans le bon ordre</b> : de la première à la dernière !')+'<div class="slots" id="sl">'+X3.map(function(x,i){return '<div class="slot" id="s'+i+'">'+(i+1)+'</div>'}).join('')+'</div><div class="ubank" id="bk2">'+o.map(function(x){return '<button class="ubk" data-i="'+x[1]+'">'+x[0]+'</button>'}).join('')+'</div><div class="btns" id="bb"></div></div>';
 A.querySelectorAll('.ubk').forEach(function(b){b.onclick=function(){if(+b.dataset.i===n){var s=document.getElementById('s'+n);s.textContent=X3[n];s.classList.add('ok');b.style.display='none';n++;confetti('s');if(n===X3.length){setSay('Bravo ! Tu connais tout le <b>cycle de l\'eau</b> !');confetti(1);document.getElementById('bb').innerHTML='<button class="go" id="nx">Terminer ›</button>';document.getElementById('nx').onclick=bilan}else setSay('Oui ! Et ensuite ?')}else{b.classList.add('no');setTimeout(function(){b.classList.remove('no')},500);setSay('Pas encore celle-là. Qu\'est-ce qui vient <b>en premier</b> ?')}}})}
