function fiches(){PB=bilan;A.innerHTML=hdr(2)+'<div class="card"><span class="lead">📖 Les fiches</span><h2>Choisis une fiche</h2>'+say('Touche un sujet pour relire sa <b>fiche</b> !')+'<div class="fgr">'+L.map(function(d,k){return '<button class="fit" data-k="'+k+'"><span>'+d.e+'</span>'+d.t+'</button>'}).join('')+'</div><div class="btns"><button class="go" id="bkf">‹ Retour</button></div></div>';
 A.querySelectorAll('.fit').forEach(function(b){b.onclick=function(){fiche(+b.dataset.k)}});document.getElementById('bkf').onclick=bilan}
function fiche(k){PB=fiches;var D=L[k],ims=[D.img,D.img2,D.img3].filter(Boolean);
 A.innerHTML=hdr(2)+'<div class="card fch"><span class="lead">Fiche '+(k+1)+' / '+L.length+'</span><h2>'+D.e+' '+D.t+'</h2>'+(D.emo&&!D.img?'<div class="femo">'+D.emo+'</div>':'')+((D.vids||D.imgs)?'':ims.map(function(m){return '<img class="fim" src="img/phen/'+m+'" alt="">'}).join(''))+D.st.map(function(s,j){return (D.vids?'<video class="fim" src="img/phen/'+D.vids[j]+'" autoplay muted loop playsinline controls></video>':D.imgs?(D.imgs[j]?(/\.mp4$/.test(D.imgs[j])?'<video class="fim" src="img/phen/'+D.imgs[j]+'" autoplay muted loop playsinline controls></video>':'<img class="fim" src="img/phen/'+D.imgs[j]+'" alt="">'):''):'')+'<div class="fq"><b>❓ '+D.q[j]+'</b><div>'+s+'</div></div>'}).join('')+'<div class="ret"><b>⭐ À retenir :</b> '+D.ret+'</div>'+(D.pro?'<div class="pro"><b>🛡️ Pour se protéger :</b> '+D.pro+'</div>':'')+'<div class="btns">'+(k>0?'<button class="go" id="pv" style="background:#8a94c4">‹</button>':'')+'<button class="go" id="ls">Toutes les fiches</button>'+(k<L.length-1?'<button class="go" id="nf">›</button>':'')+'</div></div>';(function(){var o=document.getElementById('phu');if(o)o.scrollTop=0})();
 document.getElementById('ls').onclick=fiches;if(k>0)document.getElementById('pv').onclick=function(){fiche(k-1)};if(k<L.length-1)document.getElementById('nf').onclick=function(){fiche(k+1)}}
var AC=null;function snd(t){if(!t)return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();var c=AC,n=c.currentTime,len=Math.floor(c.sampleRate*4),b=c.createBuffer(1,len,c.sampleRate),d=b.getChannelData(0),l=0;for(var i=0;i<len;i++){var w=Math.random()*2-1;l=(l+0.02*w)/1.02;d[i]=t==='wind'?w:l*14}
 function src(){var s=c.createBufferSource();s.buffer=b;return s}
 function env(g,a,pk,dur){g.gain.setValueAtTime(0.0001,n);g.gain.exponentialRampToValueAtTime(pk,n+a);g.gain.exponentialRampToValueAtTime(0.0001,n+dur)}
 if(t==='thunder'){var s1=src(),h=c.createBiquadFilter(),g1=c.createGain();h.type='highpass';h.frequency.value=1500;s1.connect(h);h.connect(g1);g1.connect(c.destination);env(g1,0.01,0.5,0.35);s1.start(n);s1.stop(n+0.4);
  var s2=src(),f=c.createBiquadFilter(),g2=c.createGain();f.type='lowpass';f.frequency.value=260;s2.connect(f);f.connect(g2);g2.connect(c.destination);g2.gain.setValueAtTime(0.0001,n+0.25);g2.gain.exponentialRampToValueAtTime(1,n+0.5);g2.gain.exponentialRampToValueAtTime(0.0001,n+3.8);s2.start(n+0.25);s2.stop(n+4)}
 if(t==='quake'){var s=src(),f=c.createBiquadFilter(),g=c.createGain(),o=c.createOscillator(),og=c.createGain();f.type='lowpass';f.frequency.value=140;s.connect(f);f.connect(g);g.connect(c.destination);o.frequency.value=9;og.gain.value=0.35;o.connect(og);og.connect(g.gain);env(g,0.3,0.9,3.6);s.start(n);o.start(n);s.stop(n+4);o.stop(n+4)}
 if(t==='wind'){var s=src(),f=c.createBiquadFilter(),g=c.createGain();f.type='bandpass';f.Q.value=1.2;f.frequency.setValueAtTime(400,n);f.frequency.linearRampToValueAtTime(1100,n+1.8);f.frequency.linearRampToValueAtTime(500,n+3.6);s.connect(f);f.connect(g);g.connect(c.destination);env(g,1.2,0.5,3.8);s.start(n);s.stop(n+4)}
 }catch(e){}}
function bilan(){try{if(typeof save!=='undefined'){save['phe-rap']=1;if(typeof persist==='function')persist()}}catch(e){}PB=function(){exo3()};A.innerHTML=hdr(2)+'<div class="card"><span class="lead">Bilan</span><h2>Bravo, '+N+' !</h2>'+say('Tu connais l\'eau, le ciel et les <b>phénomènes naturels</b> !')+'<div class="memo">☀️ Le Soleil chauffe l\'eau.<br>☁️ La vapeur forme les nuages, la pluie retombe.<br>🌀⛈️🌪️ Ouragan, tempête, tornade : des vents violents.<br>⚡ L\'éclair, c\'est la lumière ; le tonnerre, c\'est le bruit.<br>🌋🌍🌊 Volcan, séisme et tsunami viennent de l\'intérieur de la Terre.<br>🛡️ Quand c\'est dangereux, je me mets à l\'abri.</div><div class="btns"><button class="go" id="fc" style="background:#0e9a63">📖 Voir les fiches</button><button class="go" id="qt" style="background:#8a94c4">Terminer</button><button class="go" id="nx">Recommencer</button></div></div>';confetti(1);document.getElementById('nx').onclick=cartes;document.getElementById('fc').onclick=fiches;document.getElementById('qt').onclick=pquit}

